      "type": "array",
      "maxItems": 3,
      "items": {
        "type": "object",
        "required": ["id", "title", "description"],
        "properties": {
          "id": { "type": "string" },
          "title": { "type": "string" },
          "description": {
            "type": "string",
            "description": "Seed body, truncated at ~1200 chars by gate-bounce.nu to bound the enrichment at ~4 KB."
          }
